 data.profile={...data.profile,id:'me'};data.users=data.users||{};data.posts=Array.isArray(data.posts)?data.posts:[];data.notifications=Array.isArray(data.notifications)?data.notifications:[];data.topics=Array.isArray(data.topics)?data.topics:[];data.following=Array.isArray(data.following)?data.following.filter(x=>x!=='me'):[];data.favorites=Array.isArray(data.favorites)?data.favorites:[];data.settings={auto:false,interval:6,lastRun:0,...(data.settings||{})};
