function avatar(u,cls=''){return `<span class="avatar ${cls}">${u?.avatar?`<img src="${u.avatar}" alt="">`:esc((u?.name||'V').slice(0,1))}</span>`}
function user(id){return data.users[id]||data.users.me}
function score(p){const age=(now()-(p.createdAt||now()))/36e5;return (p.likes||0)*1.5+(p.comments?.length||0)*3+(p.shares||0)*2+Math.max(0,30-age)*.3}
function topicsFrom(text){return [...String(text||'').matchAll(/#([^#\s]{1,30})#/g)].map(x=>x[1])}
function postBody(text){return esc(text).replace(/#([^#\s]{1,30})#/g,'<span class="topic">#$1#</span>')}
function mediaHTML(p){const a=p.images||[];if(!a.length)return'';return `<div class="media-grid ${a.length===1?'one':''}">${a.slice(0,6).map(x=>`<img src="${x}" alt="微博图片" loading="lazy">`).join('')}</div>`}
function postHTML(p){const u=user(p.authorId),following=data.following.includes(u.id),comments=(p.comments||[]).slice(-4);return `<article class="post"><div class="post-head">${avatar(u,'sm')}<div class="grow"><div class="name" data-user="${esc(u.id)}">${esc(u.name)}</div><div class="meta">${fmt(p.createdAt)} · ${esc(p.source||'VB')} ${p.topic?`· ${esc(p.topic)}`:''}</div></div>${u.id!=='me'?`<button class="follow-mini" data-act="follow" data-id="${esc(u.id)}">${following?'已关注':'＋关注'}</button>`:''}<button class="more" data-act="more" data-id="${esc(p.id)}" aria-label="更多">···</button></div><div class="body">${postBody(p.body)}</div>${mediaHTML(p)}<div class="post-actions"><button class="${p.liked?'on':''}" data-act="like" data-id="${p.id}"><b>♡</b>${p.likes||0}</button><button data-act="comments" data-id="${p.id}"><b>◯</b>${p.comments?.length||0}</button><button data-act="repost" data-id="${p.id}"><b>↗</b>${p.shares||0}</button><button class="${data.favorites.includes(p.id)?'on':''}" data-act="favorite" data-id="${p.id}"><b>☆</b>${data.favorites.includes(p.id)?'已收藏':'收藏'}</button></div>${comments.length?`<div class="comments">${comments.map(c=>commentHTML(c,p)).join('')}</div>`:''}<form class="comment-form" data-form="comment" data-id="${p.id}"><input name="body" placeholder="写评论…"><button type="button" class="ai-comment-btn" data-act="generate-comment" data-id="${p.id}">✦ 生成评论</button><button type="submit">发送</button></form></article>`}
function commentHTML(c,p){const cu=user(c.authorId)||{name:c.author||'网友'};return `<div class="comment"><div class="comment-row">${avatar(cu,'xs')}<div class="grow"><div class="comment-text"><b data-user="${esc(c.authorId||'')}">${esc(c.author||cu.name)}</b>：${esc(c.body)}</div><div class="comment-tools"><span>${fmt(c.createdAt||p.createdAt)}</span><button data-act="reply" data-id="${p.id}" data-comment="${c.id}">回复</button><button data-act="like-comment" data-id="${p.id}" data-comment="${c.id}">赞 ${c.likes||0}</button></div>${(c.replies||[]).slice(-3).map(r=>`<div class="reply"><b>${esc(r.author)}：</b>${esc(r.body)}</div>`).join('')}${replyTarget?.postId===p.id&&replyTarget?.commentId===c.id?`<form class="comment-form" data-form="reply" data-id="${p.id}" data-comment="${c.id}"><input name="body" placeholder="回复 ${esc(c.author)}…"><button type="button" class="ai-comment-btn" data-act="generate-comment" data-id="${p.id}" data-comment="${c.id}">✦ 生成评论</button><button type="submit">发送</button></form>`:''}</div></div></div>`}
function composeHTML(){return `<section class="composer"><div class="compose-row">${avatar(data.users.me)}<textarea id="draft" placeholder="有什么新鲜事想分享？"></textarea></div><div class="composer-tools"><label class="btn">图片 <input id="image" type="file" accept="image/*" multiple hidden></label><button class="btn" data-act="topic-add"># 话题</button><button class="btn primary" data-act="publish">发布</button></div><div id="preview"></div></section>`}
function homePage(){let posts=[...data.posts];if(data.homeTab==='following')posts=posts.filter(p=>p.authorId==='me'||data.following.includes(p.authorId));else posts.sort((a,b)=>score(b)-score(a));if(searchTerm)posts=posts.filter(p=>(p.body+' '+p.author+' '+(p.topic||'')).toLowerCase().includes(searchTerm.toLowerCase()));return `<div class="feed">${composeHTML()}<div class="ai-tools"><div class="ai-note">AI 控制台 · 以下三个按钮都会直接调用你 LOVE RECORD 的 API</div><button class="btn" data-act="generate-posts">✦ 生成帖子</button><button class="btn" data-act="generate-recommend">⌁ 生成推荐内容</button><button class="btn" data-act="generate-hot">🔥 生成热搜</button></div><div class="sectionline">${data.homeTab==='following'?'关注的人':'推荐'} · ${posts.length} 条</div>${posts.length?posts.map(postHTML).join(''):`<div class="profile-empty">这里还没有微博。先关注几个账号，或者发布第一条微博吧。</div>`}</div>`}
function hotPage(){const ts=[...data.topics].map(t=>({...t,count:data.posts.filter(p=>topicsFrom(p.body).includes(t.name)||p.topic===t.name).length}));const counts={};data.posts.forEach(p=>topicsFrom(p.body).forEach(t=>counts[t]=(counts[t]||0)+1));Object.entries(counts).forEach(([name,count])=>{if(!ts.some(t=>t.name===name))ts.push({id:'topic-'+name,name,description:'正在发生的 VB 话题',count})});ts.sort((a,b)=>(b.count||0)-(a.count||0));return `<div class="panel"><div style="display:flex;align-items:center;justify-content:space-between"><h2>热搜</h2><button class="btn" data-act="generate-hot">🔥 生成热搜</button></div>${ts.length?ts.map((t,i)=>`<div class="list-row" data-topic="${esc(t.name)}"><span class="rank">${i+1}</span><div class="grow"><div class="topic-hot">#${esc(t.name)}#</div><div class="topic-desc">${esc(t.description||'正在发生的话题')} · ${t.count||0} 条微博</div></div><span class="meta">›</span></div>`).join(''):`<div class="profile-empty">还没有热搜话题。发布带 #话题# 的微博，就会出现在这里。</div>`}</div>`}
function topicPage(name){const posts=data.posts.filter(p=>topicsFrom(p.body).includes(name)||p.topic===name).sort((a,b)=>b.createdAt-a.createdAt);return `<div class="feed"><div class="panel"><h2>#${esc(name)}#</h2><div class="meta">话题页 · ${posts.length} 条微博</div></div>${posts.map(postHTML).join('')||'<div class="profile-empty">这个话题还没有微博。</div>'}</div>`}
function messagesPage(){const unread=data.notifications.filter(n=>!n.read);return `<div class="panel"><h2>消息</h2><div class="list-row" data-act="mark-read"><div class="avatar sm">♡</div><div><b>互动</b><div class="meta">${unread.length?unread.length+' 条未读消息':'暂时没有未读消息'}</div></div></div>${data.notifications.slice().reverse().map(n=>`<div class="notice"><div class="avatar xs">${esc((n.actorName||'V').slice(0,1))}</div><div><b>${esc(n.title||'新消息')}</b><p>${esc(n.body||'')}</p><span class="meta">${fmt(n.time)}</span></div></div>`).join('')}</div>`}
function profilePage(id){const u=user(id),mine=id==='me',posts=data.posts.filter(p=>p.authorId===id).sort((a,b)=>b.createdAt-a.createdAt),followers=u.followers?.length||0;return `<div class="profile"><div class="cover">${u.cover?`<img src="${u.cover}" alt="">`:''}${mine?`<label class="cover-edit">更换封面<input id="coverFile" type="file" accept="image/*" hidden></label>`:''}</div><div class="profile-info"><div class="profile-main">${mine?`<label class="profile-avatar-upload">${avatar(u,'profile-avatar')}<input id="avatarFile" type="file" accept="image/*"></label>`:avatar(u,'profile-avatar')}<div class="profile-actions">${mine?'':`<button class="btn primary" data-act="follow" data-id="${u.id}">${data.following.includes(u.id)?'已关注':'关注'}</button>`}</div></div>${mine?`<div class="profile-name profile-editable" data-act="edit-name-inline">${esc(u.name)}</div><div class="profile-bio profile-editable" data-act="edit-bio-inline">${esc(u.bio||'点击这里添加简介…')}</div>`:`<div class="profile-name">${esc(u.name)}</div><div class="profile-bio">${esc(u.bio||'这个人很神秘，还没有写简介。')}</div>`}<div class="stats"><span><b>${u.following?.length||0}</b> 关注</span><span><b>${followers}</b> 粉丝</span><span><b>${posts.reduce((n,p)=>n+(p.likes||0),0)}</b> 获赞</span></div></div><div class="profile-tabs"><button class="on">微博 ${posts.length}</button><button data-profile-tab="comments">评论</button><button data-profile-tab="likes">赞</button></div>${mine?`<div class="profile-world-link" data-act="open-world-settings"><div><b>微博世界观设定</b><div class="meta">设置世界背景、规则、参与者与 AI 用户生态</div></div><span>›</span></div>`:''}<div id="profilePosts">${posts.length?posts.map(postHTML).join(''):'<div class="profile-empty">还没有微博。</div>'}</div></div>`}
function searchPage(){return `<div class="search-page"><div class="search-field"><input id="searchInput" class="search-input" value="${esc(searchTerm)}" placeholder="搜索用户、微博、话题"><button data-act="do-search">搜索</button></div>${searchTerm?searchResults():`<div class="result-title">大家都在搜</div>${data.topics.slice(0,8).map(t=>`<div class="list-row" data-topic="${esc(t.name)}"><span>⌕</span><div class="grow"><b>#${esc(t.name)}#</b><div class="meta">话题</div></div></div>`).join('')}`}</div>`}
function searchResults(){const q=searchTerm.toLowerCase();const users=Object.values(data.users).filter(u=>(u.name+' '+u.bio).toLowerCase().includes(q)).slice(0,8);const posts=data.posts.filter(p=>(p.body+' '+p.author).toLowerCase().includes(q)).slice(0,10);return `<div class="result-title">用户</div>${users.map(u=>`<div class="list-row" data-user="${u.id}">${avatar(u,'sm')}<div class="grow"><b>${esc(u.name)}</b><div class="meta">${esc(u.bio||'VB 用户')}</div></div></div>`).join('')||'<div class="meta">没有找到用户</div>'}<div class="result-title">微博</div>${posts.map(p=>`<div class="list-row" data-post-open="${p.id}"><div class="grow"><b>${esc(p.author)}</b><div class="topic-desc">${esc(p.body.slice(0,100))}</div></div></div>`).join('')||'<div class="meta">没有找到微博</div>'}`}
function settingsPage(){
 const c=cfg(), contactsAll=allContacts(), residents=aiResidents();
 const enabled=new Set((data.enabled||[]).map(String));
 return `<div class="settings-wrap">
  <section class="settings-hero"><h2>微博世界观设定</h2><p>这里决定 VB 的时代、城市、生活规则，以及所有 AI 用户共同生活的背景。它不是一个 AI 的人设，而是一整个会自己运转的微博世界。</p></section>
  <section class="settings-card"><h3>世界背景</h3><p class="card-sub">告诉 AI：这个微博世界发生在哪里、是什么时代、有什么生活规则和社会氛围。</p><textarea id="world" placeholder="例如：这是一个与现实平行的现代城市。每个人都有工作、兴趣、朋友圈和自己的生活节奏；微博上的讨论会随着季节、节日、社会热点和居民日常不断变化。">${esc(data.world)}</textarea><div class="settings-action"><button class="btn primary" data-act="save-world">保存世界观</button></div></section>
  <section class="settings-card"><h3>参与者</h3><p class="card-sub">选择哪些 LOVE RECORD 联系人进入这个微博世界。这里是“真实联系人”，AI 居民会在下面单独管理。</p>${contactsAll.length?`<div class="contact-list">${contactsAll.map(c=>`<label class="contact-item"><span class="contact-avatar">${c.avatar||c.photo?`<img src="${esc(c.avatar||c.photo)}" alt="">`:esc(String(c.name||'?').slice(0,1))}</span><span class="grow"><span class="contact-name">${esc(c.name)}</span><span class="contact-role">${esc(c.role||c.description||'LOVE RECORD 联系人')}</span></span><input class="check contact-check" type="checkbox" data-contact="${esc(c.id)}" ${enabled.has(String(c.id))?'checked':''}></label>`).join('')}</div>`:'<div class="api-state">主设置里还没有联系人。</div>'}<div class="settings-action"><button class="btn" data-act="save-contacts">保存参与者</button></div></section>
  <section class="settings-card"><h3>世界自动更新</h3><p class="card-sub">打开 VB 时检查一次；浏览器关闭后不会承诺后台持续运行。下次打开时会按间隔补偿更新。</p><label class="switchrow"><span>打开 VB 时自动检查</span><input id="auto" class="check" type="checkbox" ${data.settings.auto?'checked':''}></label><div class="switchrow"><span>检查间隔</span><span class="interval-wrap"><input id="interval" type="number" min="1" max="72" value="${data.settings.interval}"><span>小时</span></span></div><div class="settings-action"><button class="btn" data-act="save-settings">保存设置</button></div></section>
  <section class="settings-card world-event-card"><h3>世界动态</h3><p class="card-sub">让现有的 AI 用户继续生活、发帖、评论、点赞、关注彼此，让微博世界持续发生变化。</p><div class="world-actions single"><button class="btn primary" data-act="generate">让世界发生事情</button></div></section>
  <section class="settings-card"><h3>API</h3><div class="api-state"><span class="api-dot ${c.base&&c.key&&c.model?'on':''}"></span><span>${c.base&&c.key&&c.model?'已连接 LOVE RECORD API · '+esc(c.model):'尚未配置完整 API，请先到 LOVE RECORD 主设置连接。'}</span></div></section>
 </div>`
}
function editProfileSheet(){const u=data.users.me;return `<div class="modal-back" data-act="close-sheet"><div class="sheet" onclick="event.stopPropagation()"><div class="sheet-head"><span class="sheet-title">编辑资料</span><button data-act="close-sheet">×</button></div><label class="meta">昵称</label><input id="editName" class="edit-input" value="${esc(u.name)}"><label class="meta" style="display:block;margin-top:12px">简介</label><textarea id="editBio" class="edit-input" style="width:100%;min-height:90px;border-radius:12px" placeholder="介绍一下自己…">${esc(u.bio||'')}</textarea><button class="btn primary" data-act="save-profile" style="width:100%;margin-top:12px">保存资料</button></div></div>`}
function searchSheet(){return `<div class="modal-back" data-act="close-sheet"><div class="sheet" onclick="event.stopPropagation()"><div class="sheet-head"><span class="sheet-title">搜索</span><button data-act="close-sheet">×</button></div><div class="search-field"><input id="sheetSearch" class="search-input" placeholder="搜索用户、微博、话题"><button data-act="sheet-search">搜索</button></div><div id="sheetResults"></div></div></div>`}
function shell(){injectStyle();let el=$('#vbApp');if(!el){el=document.createElement('div');el.id='vbApp';document.body.append(el)}el.innerHTML=`<div class="vb-container"><header class="top"><div class="topline"><div class="brand">VB</div><div class="searchbar" data-act="open-search">⌕&nbsp; 搜索用户、微博、话题</div><button class="topicon" data-act="notifications">♡</button><button class="topicon" data-act="close">×</button></div>${data.activeTab==='home'?`<div class="tabs"><button class="${data.homeTab==='recommend'?'on':''}" data-home="recommend">推荐</button><button class="${data.homeTab==='following'?'on':''}" data-home="following">关注</button></div>`:''}</header><main id="vbContent"></main><nav class="bottom"><button data-nav="home" class="${data.activeTab==='home'?'on':''}"><b>⌂</b>首页</button><button data-nav="hot" class="${data.activeTab==='hot'?'on':''}"><b>♨</b>热搜</button><button class="publish" data-act="compose"><b>＋</b></button><button data-nav="messages" class="${data.activeTab==='messages'?'on':''}"><b>♡</b>消息</button><button data-nav="me" class="${data.activeTab==='me'?'on':''}"><b>♙</b>我的</button></nav></div>`;el.addEventListener('click',click);el.addEventListener('submit',submit);el.addEventListener('change',change);render()}
function render(){const box=$('#vbContent');if(!box)return;if(viewUser){box.innerHTML=profilePage(viewUser);return}if(data.activeTab==='home')box.innerHTML=homePage();else if(data.activeTab==='hot')box.innerHTML=hotPage();else if(data.activeTab==='messages')box.innerHTML=messagesPage();else if(data.activeTab==='me')box.innerHTML=profilePage('me');else if(data.activeTab==='search')box.innerHTML=searchPage();else if(data.activeTab==='settings')box.innerHTML=settingsPage();}
async function fileData(f){return new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)})}
function notify(title,body,actor){data.notifications.push({id:uid(),title,body,actorName:actor||'',time:now(),read:false})}
async function askWithImages(payload,system,images=[]){
 const c=cfg();if(!c.base||!c.key||!c.model)throw Error('请先在 LOVE RECORD 主设置配置 API。');
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);
 const content=[{type:'text',text:JSON.stringify(payload)}];
 for(const src of (images||[]).slice(0,6)){if(typeof src==='string'&&src.startsWith('data:'))content.push({type:'image_url',image_url:{url:src}})}
 let r;try{r=await fetch(c.base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+c.key,'Accept':'application/json'},body:JSON.stringify({model:c.model,stream:false,messages:[{role:'system',content:system},{role:'user',content}]}),signal:controller.signal})}catch(e){if(e?.name==='AbortError')throw Error('图片理解 API 请求超时（30秒）。');throw e}finally{clearTimeout(timer)}
 const raw=await r.text();if(!r.ok)throw Error('API '+r.status+'：'+raw.slice(0,220));let j;try{j=JSON.parse(raw)}catch{throw Error('API 返回的不是有效 JSON：'+raw.slice(0,180))}let t=j.choices?.[0]?.message?.content||j.choices?.[0]?.text||'';if(Array.isArray(t))t=t.map(x=>x.text||x.content||'').join('');t=String(t).replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();try{return JSON.parse(t)}catch{const m=t.match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0])}catch{}}throw Error('AI 图片理解结果无法解析：'+t.slice(0,160))}
}

async function aiReact(post, reason='用户刚刚发布了一条微博'){
 if(!post||post.authorId!=='me')return;
 const people=activeContacts().map(c=>({id:'c-'+c.id,name:c.name,personality:c.personality||c.description||'',role:c.role||'',bio:data.users['c-'+c.id]?.bio||''}));
 const known=Object.values(data.users).filter(u=>u.type!=='me').map(u=>({id:u.id,name:u.name,bio:u.bio,type:u.type})).slice(0,50);
 if(!people.length&&!known.length)return;
 const recent=data.posts.filter(x=>x.id!==post.id).slice(0,12).map(x=>({id:x.id,authorId:x.authorId,author:x.author,body:x.body}));
 const r=post.images?.length?await askWithImages({world:data.world,participants:people,knownUsers:known,targetPost:{id:post.id,author:post.author,body:post.body},recentPosts:recent,reason,imageInstruction:'请先理解微博配图的内容，再决定互动；不要臆测图片中看不清的文字。请额外返回imageSummary，用一句到两句中文概括图片实际展示的内容，供这个微博世界后续继续理解。',task:'为这条真人用户微博生成自然的AI用户互动。优先复用已有账号；不得创建me；生成1-3条评论，必要时1-2个AI点赞动作。评论作者必须是AI账号，不得冒充真人。每条评论都要符合该账号的人设、兴趣和与上下文的关系。返回JSON：{imageSummary:string,comments:[{authorId,body}],likes:[authorId]}。'},'你是长期虚拟微博世界的互动引擎。你具备图片理解能力。只生成AI用户行为，绝不替真人发微博。严格输出JSON。',post.images):await ask({world:data.world,participants:people,knownUsers:known,targetPost:{id:post.id,author:post.author,body:post.body},recentPosts:recent,reason,task:'为这条真人用户微博生成自然的AI用户互动。优先复用已有账号；不得创建me；生成1-3条评论，必要时1-2个AI点赞动作。评论作者必须是AI账号，不得冒充真人。每条评论都要符合该账号的人设、兴趣和与上下文的关系。返回JSON：{comments:[{authorId,body}],likes:[authorId]}。'},'你是长期虚拟微博世界的互动引擎。只生成AI用户行为，绝不替真人发微博。严格输出JSON。');
 if(post.images?.length&&r.imageSummary)post.imageDescription=String(r.imageSummary).slice(0,500);
 for(const c of (r.comments||[]).slice(0,3)){const u=data.users[c.authorId];if(u&&u.type!=='me'&&String(c.body||'').trim()){post.comments=post.comments||[];post.comments.push({id:uid(),authorId:u.id,author:u.name,body:String(c.body),replies:[],createdAt:now()});notify('新的评论',u.name+' 评论了你的微博',u.name)}}
 for(const id of (r.likes||[]).slice(0,4)){const u=data.users[id];if(u&&u.type!=='me'){post.aiLikes=post.aiLikes||[];if(!post.aiLikes.includes(id)){post.aiLikes.push(id);post.likes=(post.likes||0)+1}}}
 await save();render();
}

async function publish(){const body=$('#draft')?.value.trim();if(!body){toast('先写点内容吧');return}const fs=[...($('#image')?.files||[])].slice(0,6),images=await Promise.all(fs.map(fileData));const p={id:uid(),authorId:'me',author:data.profile.name,body,images,createdAt:now(),likes:0,comments:[],shares:0,source:'VB',owner:true};data.posts.unshift(p);topicsFrom(body).forEach(name=>{if(!data.topics.some(t=>t.name===name))data.topics.push({id:uid(),name,description:'VB 用户正在讨论的话题'})});await save();render();toast('微博发布成功，正在等待 AI 用户互动…');try{status('AI 正在阅读你的微博并决定如何互动…');await aiReact(p,'真人用户刚刚发布新微博')}catch(e){status('AI 互动失败：'+e.message);toast('微博已发布，但 AI 互动暂时失败')} }
async function refreshWorldEngagement(){
 const known=Object.values(data.users).filter(u=>u.id!=='me').slice(0,50).map(u=>({id:u.id,name:u.name,bio:u.bio,role:u.role||'',interests:u.interests||''}));
 if(!known.length||!data.posts.length)return;
 const posts=data.posts.slice(0,30).map(p=>({id:p.id,authorId:p.authorId,author:p.author,body:p.body,imageDescription:p.imageDescription||'',likes:p.likes||0,comments:(p.comments||[]).slice(-3).map(c=>({authorId:c.authorId,author:c.author,body:c.body}))}));
 const r=await ask({world:data.world,users:known,posts,task:'更新这个多人微博世界的活跃度。针对已有微博，随机且合理地让不同AI用户产生点赞、评论、回复；同时让AI用户之间以及AI用户对真人账号产生少量关注变化。不要让me自动发微博。不要清空原有互动，只新增少量互动。返回JSON {postUpdates:[{postId,likes:[userId],comments:[{authorId,body,replyToCommentId}]}],follows:[{fromId,toId}]}。评论要具体且符合人物，不要重复，不要测试语。'} ,'你是长期运行的微博互动与社交图谱引擎。每次运行都让旧内容继续活跃，但不要夸张刷数据。严格输出JSON。');
 for(const u of Object.values(data.users)){u.followers=Array.isArray(u.followers)?u.followers:[]}
 for(const x of r.postUpdates||[]){const p=data.posts.find(q=>q.id===x.postId);if(!p)continue;p.likes=Number(p.likes)||0;p.aiLikes=Array.isArray(p.aiLikes)?p.aiLikes:[];for(const id of (x.likes||[]).slice(0,4)){const u=data.users[id];if(u&&u.id!=='me'&&!p.aiLikes.includes(id)){p.aiLikes.push(id);p.likes++;}}p.comments=Array.isArray(p.comments)?p.comments:[];for(const c of (x.comments||[]).slice(0,3)){const u=data.users[c.authorId];if(!u||u.id==='me'||!String(c.body||'').trim())continue;if(!p.comments.some(z=>z.authorId===u.id&&z.body===String(c.body))){p.comments.push({id:uid(),authorId:u.id,author:u.name,body:String(c.body),replies:[],createdAt:now()});notify('新的评论',u.name+' 评论了「'+p.author+'」的微博',u.name)}}}
 for(const f of r.follows||[]){const from=data.users[f.fromId],to=data.users[f.toId];if(!from||!to||from.id===to.id||from.id==='me'&&to.id==='me')continue;from.following=Array.isArray(from.following)?from.following:[];to.followers=Array.isArray(to.followers)?to.followers:[];if(!from.following.includes(to.id)){from.following.push(to.id);to.followers.push(from.id);if(to.id==='me')notify('新的关注',from.name+' 关注了你',from.name)}}
 await save();
}

