async function generatePosts(){if(busy){toast('正在生成中，请稍等…');return;}busy=true;generating('正在生成多人微博…');try{const known=Object.values(data.users).filter(u=>u.id!=='me').map(u=>({id:u.id,name:u.name,bio:u.bio,personality:u.personality||'',interests:u.interests||'',role:u.role||'',speech:u.speech||''})).slice(0,60);const r=await ask({world:data.world,currentDate:new Date().toISOString().slice(0,10),knownUsers:known,recentPosts:data.posts.slice(0,25).map(p=>({author:p.author,body:p.body,imageDescription:p.imageDescription||'',createdAt:p.createdAt})),task:'生成8-12条新的AI用户微博，必须来自至少6个不同AI账号。优先使用已有knownUsers；如果居民不足，新增最多8个稳定AI账号。绝对禁止me。每个账号内容符合自己的兴趣、职业、性格和近期生活，账号之间可自然讨论、引用或回应。不要生成“测试/信号良好/平台系统测试”等测试词。返回JSON {users:[{id,name,bio,personality,interests,role,speech}],posts:[{authorId,body,topic}]}'},'你是多人虚拟微博内容引擎。这里有很多AI用户一起玩微博。不同用户必须有不同生活、口吻、观点和关系。严格输出JSON。');for(const u of r.users||[]){if(u?.id&&u.id!=='me'&&u?.name){const id=String(u.id);data.users[id]={...(data.users[id]||{}),id,name:String(u.name),bio:String(u.bio||data.users[id]?.bio||''),personality:String(u.personality||data.users[id]?.personality||''),interests:String(u.interests||data.users[id]?.interests||''),role:String(u.role||data.users[id]?.role||''),speech:String(u.speech||data.users[id]?.speech||''),avatar:data.users[id]?.avatar||'',cover:data.users[id]?.cover||'',type:data.users[id]?.type||'random',followers:data.users[id]?.followers||[]}}}let added=0;const used=new Set();for(const x of r.posts||[]){const u=data.users[x.authorId];if(!u||u.id==='me'||!String(x.body||'').trim()||(/测试|信号良好|平台系统测试/i.test(String(x.body))))continue;if(used.has(u.id))continue;used.add(u.id);data.posts.unshift({id:uid(),authorId:u.id,author:u.name,body:String(x.body),topic:String(x.topic||''),images:[],likes:0,comments:[],shares:0,createdAt:now(),source:'VB'});topicsFrom(x.body).forEach(n=>{if(!data.topics.some(t=>t.name===n))data.topics.push({id:uid(),name:n,description:'VB 世界正在讨论'})});added++}await save();await refreshWorldEngagement();render();toast(`多人微博生成完成：${added} 条，${used.size} 位 AI 用户参与`)}catch(e){status('生成帖子失败：'+e.message);toast('生成帖子失败：'+e.message)}finally{busy=false;stopGenerating()}}
async function generateHot(){if(busy){toast('正在生成中，请稍等…');return;}busy=true;generating('正在生成实时感热搜…');try{const today=new Date().toISOString().slice(0,10);const r=await ask({currentDate:today,world:data.world,posts:data.posts.slice(0,40).map(p=>({author:p.author,body:p.body,imageDescription:p.imageDescription||'',likes:p.likes||0,comments:p.comments?.length||0})),topics:data.topics.slice(0,40),task:'生成8-12个具有‘当下感’的热搜。优先参考当前日期、当代中文互联网常用表达、近期流行梗、娱乐/生活/职场/情绪/季节等讨论方式；如果你的模型具备联网或搜索能力，请优先参考最近趋势，但绝对不要伪造无法验证的新闻。禁止“未命名用户”“测试”“平台系统测试”“信号良好”等测试型词。不要伪造真实世界突发新闻、明星新闻或具体实时事件；如果模型没有联网能力，就用当前日期+当代网络语言+世界内正在发生的事制造实时感。返回JSON {topics:[{name,description,hotScore,trend}]}'},'你是现代社交平台热搜引擎。目标是让榜单像2026年的真实互联网热搜，而不是数据库测试数据。严格输出JSON。');for(const t of r.topics||[]){const name=String(t.name||'').replace(/^#|#$/g,'').trim();if(!name||/测试|信号良好|未命名用户|平台系统/i.test(name))continue;const old=data.topics.find(x=>x.name===name);if(old){old.description=String(t.description||old.description||'');old.hotScore=Number(t.hotScore)||old.hotScore||0;old.trend=String(t.trend||old.trend||'')}else data.topics.push({id:uid(),name,description:String(t.description||'正在发生的话题'),hotScore:Number(t.hotScore)||0,trend:String(t.trend||'')})}await save();await refreshWorldEngagement();data.activeTab='hot';render();toast('热搜已更新')}catch(e){status('生成热搜失败：'+e.message);toast('生成热搜失败：'+e.message)}finally{busy=false;stopGenerating()}}
